    marked_cols = {c for c in range(w) if any(grid[r][c] == 1 for r in range(h))}
    for r in marked_rows:
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = 2
    for c in marked_cols:
        for r in range(h):
            if out[r][c] == 0:
                out[r][c] = 2
    return out

